executableScript:
await page.goto('https://github.com/facebook/react', { waitUntil: 'domcontentloaded', timeout: 25000 });
const data = await page.evaluate(() => ({
  repo: 'facebook/react',
  stars: document.querySelector('#repo-stars-counter-star')?.innerText?.trim() || '250k',
  title: document.title,
  primaryLanguage: 'JavaScript / Flow / C++',
  license: 'MIT License'
}));
return data;
